#include "SDL2Display.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include "stb_image.h"

// Embedded font data (generated by CMake from graphics/assets/Inter.ttf)
namespace Arcade {
    extern const unsigned char INTER_FONT_DATA[];
    extern const unsigned int  INTER_FONT_SIZE;
}

namespace Arcade {

SDL2Display::~SDL2Display()
{
    close();
}

// ─── Font cache ───────────────────────────────────────────────────────────────
// Fonts are loaded lazily from the embedded Inter.ttf data.
// Each distinct pixel size is cached for the lifetime of the display.
TTF_Font* SDL2Display::getCachedFont(int size)
{
    auto it = _fontCache.find(size);
    if (it != _fontCache.end())
        return it->second;

    if (INTER_FONT_SIZE == 0)
        return nullptr;

    SDL_RWops* rwops = SDL_RWFromConstMem(INTER_FONT_DATA, (int)INTER_FONT_SIZE);
    if (!rwops)
        return nullptr;

    // freesrc=1 tells SDL_ttf to close the RWops after reading
    TTF_Font* font = TTF_OpenFontRW(rwops, 1, size);
    if (font)
        _fontCache[size] = font;
    return font;
}

// ─── init / close ─────────────────────────────────────────────────────────────
void SDL2Display::init(const std::string& title)
{
    if (SDL_Init(SDL_INIT_VIDEO) < 0)
        throw std::runtime_error(std::string("SDL_Init: ") + SDL_GetError());
    const bool audioOk = (SDL_InitSubSystem(SDL_INIT_AUDIO) == 0);
    if (TTF_Init() < 0)
        throw std::runtime_error(std::string("TTF_Init: ") + TTF_GetError());

    _window = SDL_CreateWindow(title.c_str(),
        SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED,
        WIN_W, WIN_H,
        SDL_WINDOW_FULLSCREEN_DESKTOP);
    if (!_window)
        throw std::runtime_error(std::string("SDL_CreateWindow: ") + SDL_GetError());

    _renderer = SDL_CreateRenderer(_window, -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!_renderer)
        throw std::runtime_error(std::string("SDL_CreateRenderer: ") + SDL_GetError());
    SDL_RenderSetLogicalSize(_renderer, WIN_W, WIN_H);

    _lastGrid = {};
    _lastRelX = _lastRelY = -1.f;
    _open = true;

    // Warm the cache at base size so the first frame has no stutter
    if (!getCachedFont(DisplayConfig::BASE_FONT_SIZE))
        std::cerr << "[SDL2] Embedded Inter.ttf not available — text rendering disabled.\n";

    if (audioOk && Mix_OpenAudio(SDL2Config::AUDIO_FREQUENCY, MIX_DEFAULT_FORMAT,
                                 SDL2Config::AUDIO_CHANNELS, SDL2Config::AUDIO_CHUNK_SIZE) == 0)
        _mixerOpen = true;
}

void SDL2Display::close()
{
    if (!_open)
        return;

    if (_music) {
        Mix_HaltMusic();
        Mix_FreeMusic(_music);
        _music = nullptr;
    }
    for (auto& [ch, ck] : _activeChunks) {
        Mix_HaltChannel(ch);
        Mix_FreeChunk(ck);
    }
    _activeChunks.clear();
    if (_mixerOpen) {
        Mix_CloseAudio();
        _mixerOpen = false;
    }

    for (auto& [sz, font] : _fontCache)
        TTF_CloseFont(font);
    _fontCache.clear();

    if (_renderer) {
        SDL_DestroyRenderer(_renderer);
        _renderer = nullptr;
    }
    if (_window) {
        SDL_DestroyWindow(_window);
        _window = nullptr;
    }

    TTF_Quit();
    SDL_Quit();
    _open = false;
}

void SDL2Display::clear()
{
    if (!_renderer)
        return;
    SDL_SetRenderDrawColor(_renderer, 0, 0, 0, 255);
    SDL_RenderClear(_renderer);
}

// ─── Audio ────────────────────────────────────────────────────────────────────
void SDL2Display::playMusic(const unsigned char* data, unsigned int size, bool loop)
{
    if (!_mixerOpen || size == 0)
        return;
    if (_music) {
        Mix_HaltMusic();
        Mix_FreeMusic(_music);
        _music = nullptr;
    }
    SDL_RWops* rwops = SDL_RWFromConstMem(data, (int)size);
    if (!rwops)
        return;
    _music = Mix_LoadMUS_RW(rwops, 1);
    if (_music)
        Mix_PlayMusic(_music, loop ? -1 : 1);
}

void SDL2Display::playSound(const unsigned char* data, unsigned int size)
{
    if (!_mixerOpen || size == 0)
        return;

    // Release chunks from channels that have finished playing
    for (auto it = _activeChunks.begin(); it != _activeChunks.end(); ) {
        if (!Mix_Playing(it->first)) {
            Mix_FreeChunk(it->second);
            it = _activeChunks.erase(it);
        } else {
            ++it;
        }
    }

    SDL_RWops* rwops = SDL_RWFromConstMem(data, (int)size);
    if (!rwops)
        return;
    Mix_Chunk* chunk = Mix_LoadWAV_RW(rwops, 1);
    if (!chunk)
        return;
    const int channel = Mix_PlayChannel(-1, chunk, 0);
    if (channel < 0) {
        Mix_FreeChunk(chunk);
        return;
    }
    _activeChunks[channel] = chunk;
}

void SDL2Display::stopMusic()
{
    if (_mixerOpen)
        Mix_HaltMusic();
}

void SDL2Display::setVolume(int percent)
{
    if (_mixerOpen) {
        const int sdlVolume = std::clamp(percent, 0, 100) * MIX_MAX_VOLUME / 100;
        Mix_VolumeMusic(sdlVolume);
    }
}

void SDL2Display::display()
{
    if (_renderer)
        SDL_RenderPresent(_renderer);
}

// ─── fillMouseEvent ───────────────────────────────────────────────────────────
void SDL2Display::fillMouseEvent(MouseEvent& mouseEvent, int pixelX, int pixelY) const
{
    mouseEvent.relativeX = std::clamp(pixelX / (float)WIN_W, 0.f, 1.f);
    mouseEvent.relativeY = std::clamp(pixelY / (float)WIN_H, 0.f, 1.f);
    mouseEvent.gridX = -1;
    mouseEvent.gridY = -1;

    if (_lastGrid.gridWidth > 0 && _lastGrid.cellSize > 0.f) {
        const float localX = (float)(pixelX - _lastGrid.originX);
        const float localY = (float)(pixelY - _lastGrid.originY);
        const int viewX = (int)(localX / _lastGrid.cellSize);
        const int viewY = (int)(localY / _lastGrid.cellSize);

        if (viewX >= 0 && viewX < _lastGrid.viewWidth &&
            viewY >= 0 && viewY < _lastGrid.viewHeight) {
            mouseEvent.gridX = _lastGrid.cameraX + viewX;
            mouseEvent.gridY = _lastGrid.cameraY + viewY;
        }
    }
}

// ─── Input ────────────────────────────────────────────────────────────────────
std::vector<Key> SDL2Display::getHeldKeys()
{
    // SDL_GetKeyboardState is updated by SDL_PollEvent (already called in getKeys()).
    const Uint8* state = SDL_GetKeyboardState(nullptr);
    std::vector<Key> held;
    if (state[SDL_SCANCODE_UP])    held.push_back(Key::UP);
    if (state[SDL_SCANCODE_DOWN])  held.push_back(Key::DOWN);
    if (state[SDL_SCANCODE_LEFT])  held.push_back(Key::LEFT);
    if (state[SDL_SCANCODE_RIGHT]) held.push_back(Key::RIGHT);
    if (state[SDL_SCANCODE_W])     held.push_back(Key::W);
    if (state[SDL_SCANCODE_A])     held.push_back(Key::A);
    if (state[SDL_SCANCODE_S])     held.push_back(Key::S);
    if (state[SDL_SCANCODE_D])     held.push_back(Key::D);
    if (state[SDL_SCANCODE_SPACE]) held.push_back(Key::SPACE);
    return held;
}

std::vector<Key> SDL2Display::getKeys()
{
    std::vector<Key> keys;

    if (!_window)
        return keys;

    _pendingMouseEvents.clear();
    _prevRelX = _lastRelX;
    _prevRelY = _lastRelY;

    SDL_Event ev;
    while (SDL_PollEvent(&ev)) {
        switch (ev.type) {
            case SDL_QUIT:
                SDL_DestroyWindow(_window);
                _window = nullptr;
                _open = false;
                return keys;
            case SDL_KEYDOWN:
            {
                Key key = sdlKey(ev.key.keysym.sym);
                if (key != Key::NONE)
                    keys.push_back(key);
                break;
            }
            case SDL_MOUSEBUTTONDOWN:
            {
                MouseEvent mouseEvent;
                fillMouseEvent(mouseEvent, ev.button.x, ev.button.y);
                if (ev.button.button == SDL_BUTTON_LEFT)
                    mouseEvent.button = Key::MOUSE_LEFT;
                else if (ev.button.button == SDL_BUTTON_MIDDLE)
                    mouseEvent.button = Key::MOUSE_MIDDLE;
                else if (ev.button.button == SDL_BUTTON_RIGHT)
                    mouseEvent.button = Key::MOUSE_RIGHT;
                if (mouseEvent.button != Key::NONE)
                    _pendingMouseEvents.push_back(mouseEvent);
                break;
            }
            case SDL_MOUSEMOTION:
            {
                MouseEvent mouseEvent;
                fillMouseEvent(mouseEvent, ev.motion.x, ev.motion.y);
                _lastRelX = mouseEvent.relativeX;
                _lastRelY = mouseEvent.relativeY;
                _pendingMouseEvents.push_back(mouseEvent);
                break;
            }
        }
        if (ev.type == SDL_TEXTINPUT) {
            for (const char* p = ev.text.text; *p; ++p) {
                if (*p == '+') {
                    if (std::find(keys.begin(), keys.end(), Key::PLUS) == keys.end())
                        keys.push_back(Key::PLUS);
                } else if (*p == '-') {
                    if (std::find(keys.begin(), keys.end(), Key::MINUS) == keys.end())
                        keys.push_back(Key::MINUS);
                } else {
                    _textInput += *p;
                }
            }
        }
    }
    return keys;
}

std::vector<MouseEvent> SDL2Display::getMouseEvents()
{
    return _pendingMouseEvents;
}

std::pair<float,float> SDL2Display::getMousePosition() const
{
    return {_lastRelX, _lastRelY};
}

bool SDL2Display::hasMouseMoved() const
{
    return _lastRelX != _prevRelX || _lastRelY != _prevRelY;
}

Key SDL2Display::sdlKey(SDL_Keycode key) const noexcept
{
    switch (key) {
        case SDLK_UP:     return Key::UP;
        case SDLK_DOWN:   return Key::DOWN;
        case SDLK_LEFT:   return Key::LEFT;
        case SDLK_RIGHT:  return Key::RIGHT;
        case SDLK_RETURN: return Key::ENTER;
        case SDLK_ESCAPE: return Key::ESCAPE;
        case SDLK_SPACE:  return Key::SPACE;
        case SDLK_TAB:    return Key::TAB;
        case SDLK_F1:     return Key::F1;
        case SDLK_F2:     return Key::F2;
        case SDLK_F3:     return Key::F3;
        case SDLK_F4:     return Key::F4;
        case SDLK_BACKSPACE:  return Key::BACKSPACE;
        case SDLK_PLUS:       return Key::PLUS;
        case SDLK_KP_PLUS:    return Key::PLUS;
        case SDLK_EQUALS:     return Key::PLUS;
        case SDLK_MINUS:      return Key::MINUS;
        case SDLK_KP_MINUS:   return Key::MINUS;
        default:
            if (key >= SDLK_a && key <= SDLK_z)
                return static_cast<Key>(static_cast<int>(Key::A) + (key - SDLK_a));
            return Key::NONE;
    }
}

std::string SDL2Display::getTextInput()
{
    std::string out;
    std::swap(out, _textInput);
    return out;
}

// ─── drawGrid ─────────────────────────────────────────────────────────────────
void SDL2Display::drawGrid(const std::vector<Cell>& cells,
                            int gridWidth, int gridHeight,
                            float x1, float y1, float x2, float y2,
                            int focusX, int focusY,
                            const GridStyle& style)
{
    if (!_renderer || gridWidth <= 0 || gridHeight <= 0 || cells.empty())
        return;

    const float areaW = (x2 - x1) * WIN_W;
    const float areaH = (y2 - y1) * WIN_H;

    float cellSize = std::min(areaW / (float)gridWidth, areaH / (float)gridHeight);
    const bool needsCamera = (cellSize < DisplayConfig::MIN_CELL_PX);
    if (needsCamera)
        cellSize = DisplayConfig::MIN_CELL_PX;

    const int viewWidth  = needsCamera ? std::min(gridWidth,  (int)(areaW / cellSize)) : gridWidth;
    const int viewHeight = needsCamera ? std::min(gridHeight, (int)(areaH / cellSize)) : gridHeight;

    int cameraX = 0;
    int cameraY = 0;
    if (needsCamera && focusX >= 0)
        cameraX = std::clamp(focusX - viewWidth / 2, 0, std::max(0, gridWidth - viewWidth));
    if (needsCamera && focusY >= 0)
        cameraY = std::clamp(focusY - viewHeight / 2, 0, std::max(0, gridHeight - viewHeight));

    const int originX = (int)(x1 * WIN_W + (areaW - viewWidth * cellSize) / 2.f);
    const int originY = (int)(y1 * WIN_H + (areaH - viewHeight * cellSize) / 2.f);

    _lastGrid = { gridWidth, gridHeight, cellSize, originX, originY, viewWidth, viewHeight, cameraX, cameraY };

    // Dark background
    const int border = (int)style.borderPx;
    SDL_Rect backgroundRect = {
        (int)(x1 * WIN_W) - border,
        (int)(y1 * WIN_H) - border,
        (int)areaW + 2 * border,
        (int)areaH + 2 * border
    };
    SDL_SetRenderDrawColor(_renderer,
        style.backgroundColor.r,
        style.backgroundColor.g,
        style.backgroundColor.b, 255);
    SDL_RenderFillRect(_renderer, &backgroundRect);

    TTF_Font* cellFont = getCachedFont(std::max(8, (int)(cellSize * 0.75f)));

    for (int viewY = 0; viewY < viewHeight; ++viewY) {
        for (int viewX = 0; viewX < viewWidth; ++viewX) {
            const int gridX = cameraX + viewX;
            const int gridY = cameraY + viewY;

            if (gridX >= gridWidth || gridY >= gridHeight)
                continue;

            const Cell& cell = cells[gridY * gridWidth + gridX];

            const int px = originX + (int)(viewX * cellSize);
            const int py = originY + (int)(viewY * cellSize);
            const int cellWidth  = originX + (int)((viewX + 1) * cellSize) - px;
            const int cellHeight = originY + (int)((viewY + 1) * cellSize) - py;

            SDL_Rect cellRect = {px, py, cellWidth, cellHeight};

            if (cell.imageData && cell.imageSize > 0) {
                SDL_Texture* imgTex = getCachedImage(cell.imageData, cell.imageSize);
                if (imgTex) {
                    SDL_SetRenderDrawColor(_renderer,
                        cell.bgImage.r, cell.bgImage.g, cell.bgImage.b, 255);
                    SDL_RenderFillRect(_renderer, &cellRect);
                    SDL_RendererFlip flip = cell.imageFlipX ? SDL_FLIP_HORIZONTAL : SDL_FLIP_NONE;
                    SDL_RenderCopyEx(_renderer, imgTex, nullptr, &cellRect,
                                     (double)cell.imageAngle, nullptr, flip);
                    if (cell.highlight) {
                        SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_BLEND);
                        SDL_SetRenderDrawColor(_renderer,
                            style.highlightColor.r,
                            style.highlightColor.g,
                            style.highlightColor.b,
                            style.highlightColor.a);
                        SDL_RenderFillRect(_renderer, &cellRect);
                        SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_NONE);
                    }
                    continue;
                }
            }

            SDL_SetRenderDrawColor(_renderer, cell.bg.r, cell.bg.g, cell.bg.b, 255);
            SDL_RenderFillRect(_renderer, &cellRect);

            if (cell.c != ' ' && cellFont) {
                const char str[2] = {cell.c, '\0'};
                SDL_Color fg = {cell.fg.r, cell.fg.g, cell.fg.b, 255};
                SDL_Surface* surf = TTF_RenderText_Blended(cellFont, str, fg);

                if (surf) {
                    SDL_Texture* tex = SDL_CreateTextureFromSurface(_renderer, surf);
                    if (tex) {
                        int textWidth  = surf->w;
                        int textHeight = surf->h;
                        SDL_Rect dst = {px + (cellWidth - textWidth) / 2, py + (cellHeight - textHeight) / 2, textWidth, textHeight};
                        SDL_RenderCopy(_renderer, tex, nullptr, &dst);
                        SDL_DestroyTexture(tex);
                    }
                    SDL_FreeSurface(surf);
                }
            }

            if (cell.highlight) {
                SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_BLEND);
                SDL_SetRenderDrawColor(_renderer,
                    style.highlightColor.r,
                    style.highlightColor.g,
                    style.highlightColor.b,
                    style.highlightColor.a);
                SDL_RenderFillRect(_renderer, &cellRect);
                SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_NONE);
            }
        }
    }
}

// ─── drawText ─────────────────────────────────────────────────────────────────
void SDL2Display::drawText(const std::string& text, float relativeX, float relativeY,
                            const Color& fg, const Color*, float scale)
{
    if (!_renderer || text.empty())
        return;

    TTF_Font* font = getCachedFont(std::max(8, (int)(DisplayConfig::BASE_FONT_SIZE * scale)));
    if (!font)
        return;

    SDL_Color color = {fg.r, fg.g, fg.b, 255};
    SDL_Surface* surf = TTF_RenderText_Blended(font, text.c_str(), color);
    if (!surf)
        return;

    SDL_Texture* tex = SDL_CreateTextureFromSurface(_renderer, surf);
    if (tex) {
        int textWidth  = surf->w;
        int textHeight = surf->h;
        const int centerX = (int)(relativeX * WIN_W);
        const int centerY = (int)(relativeY * WIN_H);
        SDL_Rect textRect = {centerX - textWidth / 2, centerY - textHeight / 2, textWidth, textHeight};
        SDL_RenderCopy(_renderer, tex, nullptr, &textRect);
        SDL_DestroyTexture(tex);
    }
    SDL_FreeSurface(surf);
}

// ─── drawLine ─────────────────────────────────────────────────────────────────
void SDL2Display::drawLine(char c, float x1, float x2, float y,
                            const Color& fg, const Color& bg, float scale)
{
    if (!_renderer || x2 <= x1)
        return;

    const int px1 = (int)(x1 * WIN_W);
    const int px2 = (int)(x2 * WIN_W);
    const int py  = (int)(y  * WIN_H);
    const int fontSize = std::max(8, (int)(DisplayConfig::BASE_FONT_SIZE * scale));
    TTF_Font* font = getCachedFont(fontSize);

    // Measure character dimensions for the background height
    int charH = fontSize;
    int charW = fontSize / 2;
    if (font) {
        char tmp[2] = {c, '\0'};
        TTF_SizeText(font, (c != ' ') ? tmp : "o", &charW, &charH);
    }

    // Background rectangle (top 10% trimmed — glyphs don't reach the top of their metrics box)
    const int bgH    = charH * 9 / 10;
    const int bgTopY = py - charH / 2 + charH / 10; // shift top edge down by 10%
    if (bg.r || bg.g || bg.b) {
        SDL_Rect strip = {px1, bgTopY, px2 - px1, bgH};
        SDL_SetRenderDrawColor(_renderer, bg.r, bg.g, bg.b, 255);
        SDL_RenderFillRect(_renderer, &strip);
    }

    // Tile the character across the line
    if (font && c != ' ' && charW > 0 && px2 > px1) {
        const int count = std::max(1, (px2 - px1) / charW);
        const std::string str(count, c);
        SDL_Color color = {fg.r, fg.g, fg.b, 255};
        SDL_Surface* surf = TTF_RenderText_Blended(font, str.c_str(), color);
        if (surf) {
            SDL_Texture* tex = SDL_CreateTextureFromSurface(_renderer, surf);
            if (tex) {
                SDL_Rect dst = {px1, py - surf->h / 2, surf->w, surf->h};
                SDL_RenderCopy(_renderer, tex, nullptr, &dst);
                SDL_DestroyTexture(tex);
            }
            SDL_FreeSurface(surf);
        }
    }
}

void SDL2Display::drawRect(float x1, float y1, float x2, float y2, const Color& color)
{
    if (!_renderer)
        return;
    SDL_Rect r = {(int)(x1 * WIN_W), (int)(y1 * WIN_H),
                  (int)((x2 - x1) * WIN_W), (int)((y2 - y1) * WIN_H)};
    SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(_renderer, color.r, color.g, color.b, color.a);
    SDL_RenderFillRect(_renderer, &r);
    SDL_SetRenderDrawBlendMode(_renderer, SDL_BLENDMODE_NONE);
}

} // namespace Arcade

SDL_Texture* Arcade::SDL2Display::getCachedImage(const unsigned char* data, unsigned int size)
{
    auto it = _imageCache.find(data);
    if (it != _imageCache.end())
        return it->second;
    int imageWidth;
    int imageHeight;
    int channels;
    unsigned char* pixels = stbi_load_from_memory(data, (int)size, &imageWidth, &imageHeight, &channels, 4);
    if (!pixels) {
        _imageCache[data] = nullptr;
        return nullptr;
    }
    SDL_Surface* surf = SDL_CreateRGBSurfaceFrom(
        pixels, imageWidth, imageHeight, 32, imageWidth * 4,
        0x000000FF, 0x0000FF00, 0x00FF0000, 0xFF000000);
    SDL_Texture* tex = nullptr;
    if (surf) {
        tex = SDL_CreateTextureFromSurface(_renderer, surf);
        SDL_FreeSurface(surf);
    }
    stbi_image_free(pixels);
    _imageCache[data] = tex;
    return tex;
}

void Arcade::SDL2Display::clearImageCache()
{
    for (auto& [ptr, tex] : _imageCache) {
        if (tex)
            SDL_DestroyTexture(tex);
    }
    _imageCache.clear();
}

extern "C" {
    Arcade::IDisplayModule* createDisplay() { return new Arcade::SDL2Display(); }
    void destroyDisplay(Arcade::IDisplayModule* d) { delete d; }
}
